// ===== البرامج (أشهر البرامج) =====
// match = اسم البرنامج كما يظهر في show.ar داخل الحلقات
const SHOWS = [
  { id:'daheeh',   match:['الدحيح'],           name:{ar:'الدحيح',en:'Al-Daheeh'},        host:{ar:'أحمد الغندور',en:'Ahmed Al-Ghandour'} },
  { id:'fenjan',   match:['بودكاست فنجان'],     name:{ar:'فنجان',en:'Finjan'},           host:{ar:'عبدالرحمن أبومالح',en:'Abdulrahman Abumalih'} },
  { id:'socrates', match:['سقراط'],            name:{ar:'سقراط',en:'Socrates'},         host:{ar:'عبدالله البواري',en:'Al-Bawardi'} },
  { id:'bedoon',   match:['بدون ورق'],         name:{ar:'بدون ورق',en:'Bedoon Waraq'},  host:{ar:'محمد الحديثي',en:'Al-Hadithi'} },
  { id:'yasser',   match:['ياسر الحزيمي'],     name:{ar:'ياسر الحزيمي',en:'Yasser Al-Hazimi'}, host:{ar:'ياسر الحزيمي',en:'Yasser Al-Hazimi'} },
  { id:'tadweena', match:['تدوينة'],          name:{ar:'تدوينة',en:'Tadweena'},        host:{ar:'برنامج',en:'Program'} },
  { id:'baridi',   match:['بريدي'],           name:{ar:'بريدي',en:'Baridi'},          host:{ar:'برنامج',en:'Program'} },
  { id:'anfusikum',match:['وفي أنفسكم'],       name:{ar:'وفي أنفسكم',en:'Wa Fi Anfusikum'}, host:{ar:'برنامج',en:'Program'} }
];

// حلقات طويلة فقط (بدون شورتس): الحد الأدنى 15 دقيقة
const MIN_LONG_SECONDS = 15 * 60;
function durToSec(d){
  if(typeof d === 'number') return d;
  const p = String(d||'0').split(':').map(Number);
  return p.reduce(function(a, n){ return a * 60 + (n || 0); }, 0);
}
function showIdOf(p){
  const n = p && p.show && p.show.ar;
  const s = SHOWS.find(function(x){ return x.match.indexOf(n) !== -1; });
  return s ? s.id : null;
}
// دمج حلقات إضافية (js/episodes-extra.js يولّده scripts/fetch-episodes.mjs) وحذف أي شورتس
(function(){
  if(typeof EXTRA_PODCASTS !== 'undefined' && Array.isArray(EXTRA_PODCASTS)){
    const seen = new Set(PODCASTS.map(function(p){ return p.youtubeId; }));
    EXTRA_PODCASTS.forEach(function(p){ if(!seen.has(p.youtubeId)){ seen.add(p.youtubeId); PODCASTS.push(p); } });
  }
  for(let i = PODCASTS.length - 1; i >= 0; i--){
    if(!PODCASTS[i] || !PODCASTS[i].youtubeId || durToSec(PODCASTS[i].duration) < MIN_LONG_SECONDS) PODCASTS.splice(i, 1);
  }
})();
